"""Offline original draft assembly. No model or network call; human review is still required."""
import json
from pathlib import Path

ranges = {'PRE_A1':(5,20),'A1':(20,50),'A2':(40,100),'B1':(100,180),'B2':(180,300),'C1':(250,400),'C2':(300,500)}
units = json.loads(Path('curriculum/a1-b1.draft.json').read_text())

def unit(level, order, identifier, title, outcome, model, teaching, lessons):
    lo, hi = ranges[level]
    return dict(id=identifier,level=level,order=order,title=title,theme=title,outcome=outcome,grammarFocus=['word-choice','cohesion'],vocabulary=[],lessons=[lesson(level,identifier, i, skill, prompt, model, teaching, exercises) for i,(skill,prompt,exercises) in enumerate(lessons)])

def lesson(level, identifier, index, skill, prompt, model, teaching, exercises):
    lo, hi = ranges[level]
    scaffold = 'frames' if level in ('PRE_A1','A1') else 'checklist' if level=='A2' else 'outline' if level=='B1' else 'none'
    return dict(id=identifier+'-'+str(index+1),title=skill,miniLesson=dict(markdown=teaching+'\n\nLesson focus: '+skill+'. Read the model, notice the target choice, then practise it before writing your own version. Use truthful details; do not copy the model as your own experience.',modelText=model),warmups=[dict(type='choose',prompt=p,options=o,answer=a,hint=h) for p,o,a,h in exercises],task=dict(id=identifier+'-'+str(index+1)+'-task',title=skill,genre=title_genre(level),prompt=prompt,scaffold=scaffold,frames=['I am …','I like …'] if level=='PRE_A1' else [],wordBank=['because','then','also'] if level in ('A1','A2') else [],checklist=['Answer the task for the intended reader','Use your own accurate details','Read and revise before sending'],minWords=lo,maxWords=hi,isCheckpoint=index==2,targetLevel=level))

def title_genre(level):
    return {'PRE_A1':'simple sentences','A1':'short message','A2':'connected message','B1':'paragraphs','B2':'formal correspondence','C1':'application letter','C2':'critical revision'}[level]

def ex(prompt,good,bad,hint): return (prompt,[good,bad],good,hint)

# Retain all existing unit, lesson and task identifiers. Add a third lesson without altering their saved tasks.
additions = {
 'A1':('A clear reply','Write a reply to a new friend. Say who you are, what you enjoy, and when you can meet.',[ex('Choose a complete sentence.','I enjoy reading.','I enjoy.','The verb needs an object here.'),ex('Choose the clear invitation.','Can we meet on Saturday?','Saturday we?','Use a complete question.')]),
 'A2':('Explain a changed plan','Tell a friend why your visit plan has changed. Explain what happened and suggest a new time.',[ex('Link the cause to the change.','I stayed home because I was ill.','I stayed home although I was ill.','Use because for the reason.'),ex('Choose the polite new plan.','Could we meet next Sunday instead?','Meet next Sunday now.','A question gives the friend a choice.')]),
 'B1':('Support a proposal','Write to your neighbourhood group proposing one improvement. Give an example, consider a difficulty, and request a practical next step.',[ex('Choose evidence, not an unsupported claim.','Three neighbours reported broken lights last week.','Everybody hates this street.','Specific observations support a proposal.'),ex('Choose a realistic next step.','Could we ask the council for a repair schedule?','The council must fix everything tomorrow.','Ask for an achievable action.')])}
for old in units:
    skill,prompt,exercises=additions[old['level']]
    old['lessons'].append(lesson(old['level'],old['id'],2,skill,prompt,old['lessons'][-1]['miniLesson']['modelText'],'Build a complete message with a purpose, supporting detail, and a clear ending.',exercises))
    old['lessons'][1]['task']['isCheckpoint']=False

